def test_roundtrip_json_deviceauthorization():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "deviceCode": "sample",
      "userCode": "sample",
      "verificationUri": "sample",
      "expiresIn": 1,
      "interval": 1
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = DeviceAuthorization.load(original_data)
    saved_data = instance.save()
    reloaded = DeviceAuthorization.load(saved_data)
    assert reloaded is not None
    assert reloaded.device_code == "sample"
    assert reloaded.user_code == "sample"
    assert reloaded.verification_uri == "sample"
    assert reloaded.expires_in == 1
    assert reloaded.interval == 1


